// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

// Quebra o texto por linhas e remove linhas vazias
const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

// Pega a primeira linha como cabeçalhos (ex: perfil, produto, minimo, rentabilidade)
const headers = lines[0].split(",").map(h => h.trim());

// Mapeia o restante das linhas para um array de objetos
const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // Normaliza a coluna minimo para número puro
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

// Retorna no formato padronizado do n8n contendo o array 'investimentos'
return [{ json: { investimentos } }];

// Obtém todos os dados acumulados vindos do nó 'Mesclar'
const allInputs = $input.all();

let clientes = [];
let investimentos = [];

// Separa os clientes (do Webhook) e os investimentos (do CSV)
for (const item of allInputs) {
  if (item.json.clientes) {
    clientes = item.json.clientes;
  }
  if (item.json.body && item.json.body.clientes) {
    clientes = item.json.body.clientes;
  }
  if (item.json.investimentos) {
    investimentos = item.json.investimentos;
  }
}

// Caso venha direto dos nós individuais
if (clientes.length === 0 && $("Webhook").first()?.json) {
  const wh = $("Webhook").first().json;
  clientes = wh.clientes || wh.body?.clientes || [];
}
if (investimentos.length === 0 && $("Código em JavaScript").first()?.json) {
  investimentos = $("Código em JavaScript").first().json.investimentos || [];
}

// Função auxiliar para formatar valores monetários em formato brasileiro (R$ X.XXX,XX)
function formatarMoeda(valor) {
  const num = typeof valor === 'number' ? valor : parseFloat(valor) || 0;
  return "R$ " + num.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Função para converter saldo texto/numérico para número puro
function extrairNumero(val) {
  if (typeof val === 'number') return val;
  if (!val) return 0;
  const numLimpo = String(val).replace(/R\$\s?/, '').replace(/\./g, '').replace(',', '.').trim();
  return parseFloat(numLimpo) || 0;
}

// Processa o match entre clientes e opções de investimentos
const resultados = clientes.map(cliente => {
  const saldoNum = extrairNumero(cliente.saldo);
  const saldoTexto = typeof cliente.saldo === 'string' && cliente.saldo.includes('R$') 
    ? cliente.saldo 
    : formatarMoeda(saldoNum);

  // Busca investimentos compatíveis com o perfil do cliente e onde o saldo seja >= mínimo
  const opcoesCompativeis = investimentos.filter(inv => 
    inv.perfil.toLowerCase() === cliente.perfil.toLowerCase() && saldoNum >= inv.minimo
  );

  // Seleciona o melhor produto (com maior valor mínimo dentro do alcance do cliente ou o primeiro)
  let melhorOpcao = opcoesCompativeis.length > 0 
    ? opcoesCompativeis.sort((a, b) => b.minimo - a.minimo)[0]
    : investimentos.find(inv => inv.perfil.toLowerCase() === cliente.perfil.toLowerCase()) || investimentos[0];

  const minimoTexto = formatarMoeda(melhorOpcao.minimo);
  const motivo = saldoNum >= melhorOpcao.minimo ? "saldo_ok" : "saldo_insuficiente";

  // Gera as 3 sugestões de mensagens personalizadas
  const msg0 = `Olá ${cliente.nome}! Pelo seu perfil (${cliente.perfil}), uma boa opção é **${melhorOpcao.produto}** (mínimo ${minimoTexto}). Com seu saldo atual (${saldoTexto}), você já consegue investir. Rentabilidade: ${melhorOpcao.rentabilidade}.`;

  const msg1 = `Oi ${cliente.nome}! Recomendação para perfil ${cliente.perfil}: **${melhorOpcao.produto}** (mínimo ${minimoTexto}). Seu saldo (${saldoTexto}) já atende o mínimo. Rentabilidade: ${melhorOpcao.rentabilidade}.`;

  const msg2 = `${cliente.nome}, indo direto ao ponto: para o perfil ${cliente.perfil}, **${melhorOpcao.produto}** (mínimo ${minimoTexto}). Você tem ${saldoTexto}, então dá pra aplicar. Rentabilidade: ${melhorOpcao.rentabilidade}.`;

  const mensagens = [msg0, msg1, msg2];

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    recomendacao: {
      perfil: melhorOpcao.perfil,
      produto: melhorOpcao.produto,
      minimo: melhorOpcao.minimo,
      rentabilidade: melhorOpcao.rentabilidade
    },
    motivo: motivo,
    mensagens: mensagens,
    mensagem_escolhida: mensagens[0]
  };
});

// Retorna o objeto na estrutura exatamente igual à imagem de OUTPUT do n8n
return [{
  json: {
    ok: true,
    total_clientes: clientes.length,
    total_investimentos: investimentos.length,
    resultados: resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// Retorna UM ITEM por cliente (formato de tabela do n8n)
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

