return $input.all().map((item, index) => {
  // 1. Busca o e-mail do cliente vindo do nó anterior ('Code normalizar msg')
  let toEmail = "";
  try {
    toEmail = $("Code normalizar msg").all()[index]?.json?.email_to || 
              $("Code normalizar msg").all()[index]?.json?.email || "";
  } catch (e) {
    toEmail = item.json.email_to || item.json.to || item.json.email || "";
  }

  // 2. Tenta extrair a string de texto retornada pela LLM de qualquer estrutura
  let rawText = "";

  if (typeof item.json === "string") {
    rawText = item.json;
  } else if (item.json.text) {
    rawText = item.json.text;
  } else if (item.json.message?.content) {
    rawText = item.json.message.content;
  } else if (item.json.output) {
    rawText = typeof item.json.output === "string" ? item.json.output : JSON.stringify(item.json.output);
  } else if (item.json.saída) {
    const s = item.json.saída;
    if (Array.isArray(s) && s[0]?.contente?.[0]?.texto) {
      rawText = s[0].contente[0].texto;
    } else {
      rawText = typeof s === "string" ? s : JSON.stringify(s);
    }
  } else {
    // Busca qualquer valor do objeto que contenha o JSON em formato de string
    rawText = JSON.stringify(item.json);
  }

  // 3. Limpa formatações Markdown (ex: ```json ... ```)
  rawText = rawText
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // 4. Converte a string extraída para Objeto JSON
  let parsed = {};
  try {
    // Procura onde começa '{' e onde termina '}' caso haja texto ao redor
    const firstBrace = rawText.indexOf('{');
    const lastBrace = rawText.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
      rawText = rawText.substring(firstBrace, lastBrace + 1);
    }
    parsed = JSON.parse(rawText);
  } catch (err) {
    parsed = {};
  }

  // 5. Monta os valores garantindo que nada fique vazio
  const subject = parsed.subject || parsed.assunto || "Sugestão de Investimento Personalizada";
  const textBody = parsed.text_body || parsed.corpo_do_texto || parsed.text || rawText;

  // Cria o html_body com tags <p> caso a LLM não tenha enviado a chave html_body pronta
  let htmlBody = parsed.html_body;
  if (!htmlBody) {
    htmlBody = textBody
      .split("\n\n")
      .map(p => `<p>${p.replace(/\n/g, "<br>")}</p>`)
      .join("");
  }

  // Retorna com as colunas EXATAS: to, subject, text_body, html_body
  return {
    json: {
      to: toEmail,
      subject: subject,
      text_body: textBody,
      html_body: htmlBody
    }
  };
});
